        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Length++;
        } else if (c <= 0x7FF) {
            utf8Length += 2;
        } else if (c <= 0xFFFF) {
            utf8Length += 3;
        } else {
            utf8Length += 4;
        }
