    int utf8Index = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utf8Bytes[utf8Index++] = (byte) c;
        } else if (c <= 0x7FF) {
            utf8Bytes[utf8Index++] = (byte) (0xC0 | ((c >> 6) & 0x1F));
            utf8Bytes[utf8Index++] = (byte) (0x80 | (c & 0x3F));
        } else if (c <= 0xFFFF) {
            utf8Bytes[utf8Index++] = (byte) (0xE0 | ((c >> 12) & 0x0F));
            utf8Bytes[utf8Index++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            utf8Bytes[utf8Index++] = (byte) (0x80 | (c & 0x3F));
        } else {
