public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath.startsWith("/")) {
        throw new IllegalArgumentException("Relative path cannot start with /");
    }

    // Split the path and relative path into their components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is trying to go up more levels than the path has
    if (relativePathComponents.length > pathComponents.length) {
        throw new IllegalArgumentException("Relative path has more levels than the path");
    }

    // Build the new path by combining the path components with the relative path components
    StringBuilder newPath = new StringBuilder();
    for (int i = 0; i < relativePathComponents.length; i++) {
        String relativePathComponent = relativePathComponents[i];
        if (relativePathComponent.equals("..")) {
            // If the relative path component is "..", remove the last component from the path
            if (newPath.length() > 0) {
                newPath.delete(newPath.length() - 1, newPath.length());
            }
        } else {
            // Otherwise, add the relative path component to the new path
            newPath.append(relativePathComponent);
        }
    }

    // Add any remaining path components to the new path
    for (int i = relativePathComponents.length; i < pathComponents.length; i++) {
        newPath.append("/");
        newPath.append(pathComponents[i]);
    }

    return newPath.toString();
}

